mapper.select:
select common_id as commonId ,delivery_time as deliveryTime from ${database.prefix.goods}hou_goods_common
where common_id in

    #{id}

SELECT id, complaints_id, complaints_type, complaints_reason, complaints_voucher, complaints_contact, complaints_goodsid, seller_reason, complaints_status, compensation_amount, compensation_status, ooc.create_time, revoke_num, order_id, ooc.user_id, failure_time, seller_voucher, ooc.shop_id, shop_name FROM ${database.prefix.order}hou_order_complaints ooc LEFT JOIN ${database.prefix.supplier}hou_shop_base gmsb ON gmsb.supplier_shop_id = ooc.shop_id WHERE 1 = 1 and ooc.user_id = #{param.userId}
and complaints_id = #{param.complaintsId}
and order_id = #{param.orderId}
and complaints_type = #{param.complaintsType}
and complaints_status = #{param.complaintsStatus}
order by ooc.create_time desc

select id as id,complaints_id as complaintsId,complaints_type as complaintsType,complaints_status as complaintsStatus
FROM ${database.prefix.order}hou_order_complaints
where order_id = #{param.orderId}
and is_platform = 0
and user_id = #{param.userId}

SELECT ooc.id, compensation_amount, complaints_id, complaints_type, complaints_reason, order_id, ooc.create_time, fund_destination, complaints_goodsid, complaints_status, failure_time, sb.shop_name, sb.shop_type, ui.user_name FROM ${database.prefix.order}hou_order_complaints ooc LEFT JOIN ${database.prefix.supplier}hou_shop_base sb ON ooc.shop_id = sb.supplier_shop_id LEFT JOIN ${database.prefix.userms}hou_user_info ui ON ooc.user_id = ui.user_id WHERE 1 = 1 AND complaints_status != 0 AND complaints_status != 3
and complaints_type = #{param.complaintsType}
and sb.shop_type = #{param.shopType}
and order_id = #{param.orderId}
and complaints_id = #{param.complaintsId}
and ooc.create_time between #{param.startTime} and #{param.endTime}
and complaints_status = #{param.complaintsStatus}
and ui.user_name like CONCAT('%',#{param.userName},'%')
and sb.shop_name like CONCAT('%',#{param.shopName},'%')
order by ooc.create_time desc
and complaints_status = 4 order by failure_time asc

SELECT oog.common_id, oog.goods_id, oog.goods_image, oog.goods_name, oog.order_goods_amount, oog.goods_price, oog.order_goods_num, oog.order_spec_chineseValue, oog.goods_return_status, oog.goods_refund_status, oog.shipping_fee, oog.order_goods_payment_amount, oog.order_goods_returnnum, gb.goods_spec, oob.order_payment_amount, oob.order_shipping_fee, sb.shop_name, oob.order_id, oob.order_create_time, oob.order_status, oor.return_state, oob.order_refund_status, oob.order_return_status, gc.delivery_time, oog.order_goods_id_deliver, oob.order_shipping_time as orderShippingTime FROM ${database.prefix.order}hou_order_goods oog left join ${database.prefix.order}hou_order_base oob on oob.order_id = oog.order_id left join ${database.prefix.order}hou_order_return oor on oob.order_id = oor.order_id left join ${database.prefix.goods}hou_goods_base gb on gb.goods_id = oog.goods_id left join ${database.prefix.goods}hou_goods_common gc on gc.common_id = gb.common_id left join ${database.prefix.supplier}hou_shop_base sb on sb.supplier_shop_id = oob.shop_id where oog.order_id = #{param.orderId}
and oog.goods_id in
#{id}
